var n=`0250-baklava`;var t=`world-0250`;var i=`GR`;var o=`southern-europe`;var r=8;var s=76;var l={en:`Baklava`,ua:`Пахлава`};var u={en:`A traditional Greece dish made with phyllo pastry, walnut, lemon juice. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Греція. Основні інгредієнти: тісто філо, волоський горіх, лимонний сік. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:19,i:[[`phyllo-pastry`,420,`g`],[`walnut`,370,`g`],[`unsalted-butter`,185,`g`],[`ground-cinnamon`,5,`g`]]},{en:`Bake in a preheated 180°C oven for about 45 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 45 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:45,i:[]},{en:`Simmer the sugar, water, honey and lemon juice for about 10 minutes into syrup; let it cool, then pour over freshly baked, hot baklava and rest to absorb.`,ua:`Зваріть із цукру, води, меду та лимонного соку сироп протягом приблизно 10 хвилин; охолодіть і полийте гарячу щойно спечену пахлаву, залиште для просочування.`,t:[`reducing-sauce`],m:10,i:[[`white-granulated-sugar`,280,`g`],[`water`,230,`ml`],[`honey`,120,`g`],[`lemon-juice`,35,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[]}];var g={slug:n,id:t,country:`GR`,region:o,servings:8,minutes:76,title:l,text:u,steps:d};export{i as country,g as default,t as id,s as minutes,o as region,r as servings,n as slug,d as steps,u as text,l as title};